const clean = s => s.replace(/[​-‍⁠﻿­]/g,'').replace(/[?&][\w-]+=[^\s"']*/g,'[q]').replace(/\s+/g,' ').trim();
const rows = [];
let pages = 0;
for (let p=1; p<=12; p++) {
  const r = await fetch(`/tenders/VG-2027-7093/questions-content?page=${p}`, {credentials:'include'});
  if (!r.ok) { rows.push(`page ${p}: HTTP ${r.status}`); break; }
  const d = new DOMParser().parseFromString(await r.text(), 'text/html');
  d.querySelectorAll('script,style,noscript,template').forEach(e=>e.remove());
  const trs = [...d.querySelectorAll('tr')].filter(tr=>/\d{4}/.test(tr.textContent));
  if (!trs.length) { rows.push(`page ${p}: no rows`); break; }
  pages = p;
  trs.forEach(tr=>rows.push(`p${p} | ` + clean(tr.textContent)));
  if (!d.querySelector('a[href*="page="]') ) break;
}
window.__qa = rows;
rows.length + ' rows, pages ' + pages

