<p id="load-status" role="status"></p><script>
async function loadRows(button){
button.disabled=true;
try{
const response=await fetch(button.dataset.url,{headers:{'X-Sites-Fragment':'rows'}});
if(response.redirected){window.top.location.href=response.url;return;}
if(!response.ok){document.getElementById('load-status').textContent=button.dataset.loadFailed;return;}
const parsed=new DOMParser().parseFromString(await response.text(),'text/html');
const login=parsed.querySelector('a[data-sites-login]');
if(login){window.top.location.href=login.href;return;}
if(!parsed.getElementById(button.dataset.target)){location.href=button.dataset.url;return;}
document.getElementById(button.dataset.target).append(...parsed.getElementById(button.dataset.target).children);
const next=parsed.querySelector('button[data-url]');
if(next)button.dataset.url=next.dataset.url;else button.remove();
}catch{document.getElementById('load-status').textContent=button.dataset.connectionFailed;}
finally{button.disabled=false;}
}
