const click=b=>{setTimeout(()=>b.click(),60)}; const btn=t=>[...document.querySelectorAll('main button')].find(x=>x.innerText.trim()===t); const set=(sel,v)=>{const e=document.querySelector(sel); e.value=v; e.dispatchEvent(new Event('input',{bubbles:true})); e.dispatchEvent(new Event('change',{bubbles:true})); return e.value};
if(location.pathname==='/consent'){click(document.querySelector('button[type=submit]')); return 'consent accepted';}
if(location.pathname.includes('/login')) return 'LOGIN NEEDED';
const h=(document.querySelector('main h2,main h3')?.innerText||'').trim();
