 for(let i=0;i<4;i++){const s=document.querySelector('select[name='+f[i]+']'); if(s.disabled) return k+': '+f[i]+' disabled?'; if(s.value!==p[i]){ if(![...s.options].some(o=>o.value===p[i])) return k+': option '+p[i]+' missing for '+f[i]+' ['+[...s.options].map(o=>o.value).join('/')+']'; set('select[name='+f[i]+']',p[i]); click(btn('Auswahl übernehmen')); return k+': '+f[i]+'='+p[i];}}
 const m=document.querySelector('select[name=material]'); if(![...m.options].some(o=>o.value===p[4])) return k+': material '+p[4]+' missing ['+[...m.options].map(o=>o.value).join('/')+']';
 set('select[name=material]',p[4]); set('input[name=quantity]',p[5]); set('input[name=price]',p[6]); set('input[name=base_price]',p[7]); set('input[name=surcharge]',p[8]); set('input[name=packaging]',p[9]); set('input[name=rebate]',p[10]);
 const l=document.querySelector('select[name=lead]'); set('select[name=lead]',[...l.options].find(o=>o.text.trim()===p[11]).value);
 click([...document.querySelectorAll('main button[name=action]')].find(x=>x.innerText.trim()==='Weiter')); return k+': all fields filled, Weiter';}
if(h==='Konditionen'){set('input[name=discount]','5'); set('input[name=total]','356.949,62'); click([...document.querySelectorAll('main button[name=action]')].find(x=>x.value==='next')); return 'step 8: 5 % / 356.949,62';}
if(h==='Erklärungen'){const a=document.querySelector('input[name=acknowledge]'), t=document.querySelector('input[name=terms]'); a.checked=true; t.checked=false; click(btn('Weiter')); return 'step 9: documents acknowledged, AGB unticked';}
if(h==='Prüfen und signieren') return 'REVIEW';
return 'unknown page: '+h;})()

