1	"""The browser side: a compact text view of whatever page is open, and actions on its numbered elements.
2	
3	Nothing here knows the websites. The view renders any page the same way: text in reading order, tables as rows,
4	frames after the page, and every element the model can act on as [n kind "label"]. Code helps where the brief allows
5	it (logging in with the run's credentials, retrying error pages, reading a document the model picked); the model
6	chooses where to go and what to do.
7	"""
8	import asyncio
9	import base64
10	import io
11	import re
12	import tempfile
13	import zipfile
14	from html.parser import HTMLParser
15	from pathlib import Path
16	from urllib.parse import urljoin, urlparse
17	
18	MAX_VIEW = 16000  # characters of the page shown at once; more() pages through the rest
19	MAX_DOCUMENT = 40000
20	
21	# Renders the document of one frame and numbers what can be acted on, starting at `start`.
22	RENDER = r"""
23	(start) => {
24	  let n = start, line = '', inCell = 0;
25	  const lines = [];
26	  const flush = () => { const t = line.replace(/[​-‍⁠﻿­]/g, '').replace(/[ \t ]+/g, ' ').trim(); if (t && t !== lines[lines.length - 1]) lines.push(t); line = ''; };
27	  const brk = () => { if (inCell) line += ' '; else flush(); };
28	  const clip = (s, k) => { s = String(s || '').replace(/[​-‍⁠﻿­]/g, '').replace(/\s+/g, ' ').trim(); return s.length > k ? s.slice(0, k) + '…' : s; };
29	  const q = (s) => JSON.stringify(s);
30	  const SKIP = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'HEAD', 'META', 'LINK', 'OPTION', 'defs', 'style']);
31	  const generated = (el, which) => {  // text a style sheet adds before or after an element
32	    const c = getComputedStyle(el, which).content;
33	    return c && c !== 'none' && c !== 'normal' && /^["']/.test(c) ? c.slice(1, -1) : '';
34	  };
35	  const ROLES = new Set(['button', 'link', 'tab', 'menuitem', 'menuitemcheckbox', 'menuitemradio', 'checkbox', 'radio',
36	    'option', 'switch', 'treeitem', 'combobox', 'textbox', 'searchbox']);
37	  const CONTROLS = 'a[href],button,input:not([type=hidden]),select,textarea,[role=button],[role=link],[onclick]';
38	  document.querySelectorAll('[data-agent-ref]').forEach((e) => e.removeAttribute('data-agent-ref'));
39	
40	  const labelOf = (el) => {
41	    let s = el.getAttribute('aria-label') || '';
