147	  const password = [...document.querySelectorAll('input[type=password]')].find(visible);
148	  if (!password) return false;
149	  const fields = [...(password.form || document).querySelectorAll('input')].filter((e) => visible(e)
150	    && !['password', 'hidden', 'checkbox', 'radio', 'submit', 'button', 'image', 'reset'].includes(e.type));
151	  const before = fields.filter((e) => e.compareDocumentPosition(password) & Node.DOCUMENT_POSITION_FOLLOWING);
152	  const user = before.length ? before[before.length - 1] : fields[0];
153	  password.setAttribute('data-agent-login', 'password');
154	  if (user) user.setAttribute('data-agent-login', 'user');
