159	# Fetches a URL inside the page, with its cookies and through the browser's own network path.
160	FETCH = r"""
161	async (url) => {
162	  const r = await fetch(url, { credentials: 'include' });
163	  const bytes = new Uint8Array(await r.arrayBuffer());
164	  let bin = '';
165	  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
166	  return { status: r.status, type: r.headers.get('content-type') || '', name: r.headers.get('content-disposition') || '',
167	           url: r.url, data: btoa(bin) };
168	}
