177	class Site:
178	    """One website, driven in its own browser: the active tab, its numbered elements, dialogs, new tabs, downloads."""
179	
180	    def __init__(self, access: dict, context, page, log=print):
181	        self.id = access.get("siteId") or urlparse(access["url"]).hostname
182	        self.url = access["url"]
183	        self.credentials = access.get("credentials") or {}
184	        self.context, self.page, self.log = context, page, log
185	        self.refs: dict[int, object] = {}  # element number -> the frame it is in
186	        self.events: list[str] = []  # dialogs, tabs and downloads since the last view
187	        self.downloads: list[Path] = []
188	        self.full_view, self.shown = "", 0
189	        self.lock = asyncio.Lock()  # one agent at a time drives this browser
190	        context.on("page", self._new_tab)
191	        self._watch(page)
192	
193	    # --- events -------------------------------------------------------------------------------------------------
194	
195	    def _watch(self, page):
196	        page.on("dialog", self._dialog)
197	        page.on("download", self._download)
198	
199	    def _new_tab(self, page):
200	        self._watch(page)
201	        self.page = page
202	        self.events.append("A new tab opened and is now the active tab.")
203	
204	    async def _dialog(self, dialog):
205	        # Browser dialogs block the page until answered. The agents only trigger them on purpose (the final
206	        # confirmation of a bid is one), so they are accepted and reported in the next view.
207	        self.events.append(f"A browser {dialog.type} dialog said {short(dialog.message)!r}; it was accepted.")
208	        try:
209	            await dialog.accept()
210	        except Exception:
211	            pass
212	
213	    async def _download(self, download):
214	        target = Path(tempfile.mkdtemp()) / (download.suggested_filename or "download")
215	        try:
216	            await download.save_as(target)
217	        except Exception as error:
218	            self.events.append(f"A download failed: {short(error)}")
219	            return
220	        self.downloads.append(target)
221	        self.events.append(f"Downloaded {target.name!r}: read it with read_document(download={len(self.downloads)}).")
222	
223	    async def _active(self):
224	        if self.page.is_closed():
225	            open_pages = [page for page in self.context.pages if not page.is_closed()]
226	            self.page = open_pages[-1] if open_pages else await self.context.new_page()
227	            self.events.append("The tab closed; switched to the previous tab.")
228	        return self.page
229	
230	    async def _settle(self):
231	        page = await self._active()
232	        for state, timeout in (("domcontentloaded", 10000), ("networkidle", 1500)):
233	            try:
234	                await page.wait_for_load_state(state, timeout=timeout)
235	            except Exception:
236	                pass
237	        await asyncio.sleep(0.2)
238	
239	    # --- the view -----------------------------------------------------------------------------------------------
240	
241	    async def view(self) -> str:
242	        """The page as text, from the top; long pages are cut, more() shows the rest."""
243	        page = await self._active()
244	        self.refs, number, parts = {}, 1, []
245	        for frame in page.frames:
246	            try:
247	                rendered = await frame.evaluate(RENDER, number)
248	            except Exception:
249	                continue
250	            for ref in range(number, rendered["next"]):
251	                self.refs[ref] = frame
252	            number = rendered["next"]
253	            if frame is page.main_frame:
254	                parts.insert(0, rendered["text"])
255	            elif rendered["text"].strip():
256	                parts.append(f"--- inside frame {frame.name or ''} {short(frame.url, 120)} ---\n{rendered['text']}")
257	            else:
258	                parts.append(f"--- frame {short(frame.url, 120)} shows nothing here: open it with goto() to read it ---")
259	        try:
260	            title = await page.title()
261	        except Exception:
262	            title = ""
263	        tabs = [p for p in self.context.pages if not p.is_closed()]
264	        header = f"URL: {page.url}\nTitle: {title}\n"
265	        if len(tabs) > 1:
266	            header += "Tabs: " + " | ".join(f"{i}{' (active)' if p is page else ''}: {short(p.url, 80)}"
267	                                            for i, p in enumerate(tabs)) + "\n"
268	        if self.events:
269	            header += "".join(f"Event: {event}\n" for event in self.events)
270	            self.events = []
271	        self.full_view = header + "\n" + "\n\n".join(parts)
272	        return self._part(0)
273	
274	    def _part(self, start: int) -> str:
275	        end = start + MAX_VIEW
276	        self.shown = end
277	        text = self.full_view[start:end]
278	        if start:
279	            text = f"[page text from character {start}]\n" + text
280	        if end < len(self.full_view):
281	            text += f"\n[… {len(self.full_view) - end} more characters: more() shows them, find(text) searches them]"
282	        return text
283	
284	    async def more(self) -> str:
285	        if self.shown >= len(self.full_view):
286	            return "That was the end of the page."
287	        return self._part(self.shown)
288	
289	    async def find(self, text: str) -> str:
290	        """Lines of the current page containing `text` (case-insensitive), with the line after each."""
291	        lines = self.full_view.splitlines()
292	        hits = [i for i, line in enumerate(lines) if text.lower() in line.lower()]
293	        if not hits:
294	            return f"{text!r} is not on the current page (as of the last view)."
295	        return "\n".join("\n".join(lines[i:i + 2]) for i in hits[:40])
