297	    # --- actions ------------------------------------------------------------------------------------------------
298	
299	    def _element(self, ref):
300	        frame = self.refs.get(int(ref))
301	        if frame is None:
302	            raise LookupError(f"There is no element [{ref}] on the page as last viewed; look at the current view.")
303	        return frame.locator(f'[data-agent-ref="{int(ref)}"]').first
304	
305	    async def click(self, ref) -> str:
306	        element = self._element(ref)
307	        try:
308	            await element.click(timeout=5000)
309	        except Exception as error:
310	            try:  # covered by an overlay or off screen: a DOM click still reaches the element's handler
311	                await element.evaluate("(e) => e.click()", timeout=3000)
312	            except Exception:
313	                return f"Could not click [{ref}]: {short(error)}\n\n" + await self.view()
314	        await self._settle()
315	        return await self.view()
316	
317	    async def fill(self, fields: list[dict]) -> str:
318	        """Several inputs at once: text is typed, selects choose the option by label or value, checkboxes take
319	        true/false."""
320	        problems = []
321	        for field in fields:
322	            ref, value = field.get("ref"), field.get("value")
323	            try:
324	                element = self._element(ref)
325	                kind = await element.evaluate("(e) => e.tagName === 'SELECT' ? 'select' : (e.type || '').toLowerCase()",
326	                                              timeout=4000)
327	                if kind == "select":
328	                    try:
329	                        await element.select_option(label=str(value), timeout=3000)
330	                    except Exception:
331	                        await element.select_option(value=str(value), timeout=3000)
332	                elif kind in ("checkbox", "radio"):
333	                    want = value if isinstance(value, bool) else str(value).lower() in ("true", "1", "yes", "ja", "on")
334	                    try:
335	                        await element.set_checked(want, timeout=3000)
336	                    except Exception:
337	                        await element.set_checked(want, force=True, timeout=3000)
338	                else:
339	                    await element.fill(str(value), timeout=4000)
340	            except Exception as error:
341	                problems.append(f"[{ref}]: {short(error, 200)}")
342	        await self._settle()
343	        report = "Filled." if not problems else "Problems: " + "; ".join(problems)
344	        return report + "\n\n" + await self.view()
345	
346	    async def type(self, ref, text: str, enter: bool = False) -> str:
347	        element = self._element(ref)
348	        try:
349	            await element.fill(text, timeout=4000)
350	        except Exception:
351	            await element.click(timeout=3000)
352	            await (await self._active()).keyboard.type(text)
353	        if enter:
354	            await element.press("Enter")
355	        await self._settle()
356	        return await self.view()
