358	    async def drag(self, ref, dx: float | None = None, dy: float = 0) -> str:
359	        """Drags an element with the mouse, such as a slider's handle or a range input; without dx, all the way to
360	        the right end of its track."""
361	        element = self._element(ref)
362	        page = await self._active()
363	        await element.scroll_into_view_if_needed(timeout=3000)
364	        box = await element.bounding_box()
365	        if not box:
366	            return "The element is not on screen.\n\n" + await self.view()
367	        track = box
368	        if box["width"] < 60:  # a small handle: its track is the parent
369	            track = await element.evaluate("(e) => { const r = e.parentElement.getBoundingClientRect(); "
370	                                           "return {x: r.x, y: r.y, width: r.width, height: r.height}; }",
371	                                           timeout=4000)
372	        slider = await element.evaluate("(e) => e.type === 'range' ? {min: +e.min || 0, max: +(e.max || 100), "
373	                                        "value: +e.value} : null", timeout=4000)
374	        if slider:
375	            share = (slider["value"] - slider["min"]) / max(1e-9, slider["max"] - slider["min"])
376	            x = box["x"] + 8 + (box["width"] - 16) * share
377	        else:
378	            x = box["x"] + min(10, box["width"] / 2)
379	        y = box["y"] + box["height"] / 2
380	        end_x = x + dx if dx is not None else track["x"] + track["width"] + 30
381	        await page.mouse.move(x, y)
382	        await page.mouse.down()
383	        for step in range(1, 21):
384	            await page.mouse.move(x + (end_x - x) * step / 20, y + dy * step / 20)
385	            await asyncio.sleep(0.02)
386	        await page.mouse.up()
387	        await self._settle()
388	        report = ""
389	        if slider:  # say where the slider ended up, so the model knows whether the drag worked
390	            try:
391	                state = await element.evaluate("(e) => ({value: e.value, max: e.max || '100'})", timeout=2000)
392	                report = f"The slider is now at {state['value']} of {state['max']}.\n\n"
393	            except Exception:
394	                report = "The slider was replaced by the page (it may have unlocked).\n\n"
395	        return report + await self.view()
