405	    async def goto(self, url: str) -> str:
406	        page = await self._active()
407	        target = urljoin(page.url if page.url.startswith("http") else self.url, url)
408	        for attempt in range(3):  # flaky error pages: retry a server error a few times
409	            try:
410	                response = await page.goto(target, wait_until="domcontentloaded", timeout=20000)
411	                if response is None or response.status < 500:
412	                    break
413	                self.log(f"[{self.id}] HTTP {response.status} on {target}, retrying")
414	            except Exception as error:
415	                self.log(f"[{self.id}] {short(error, 120)}, retrying")
416	            await asyncio.sleep(1.5 * (attempt + 1))
417	        await self._settle()
418	        return await self.view()
