503	            fetched = await frame.evaluate(FETCH, url)
504	        except Exception:
505	            fetched = await page.main_frame.evaluate(FETCH, url)
506	        data = base64.b64decode(fetched["data"])
507	        if "html" in fetched["type"] and "attachment" not in fetched["name"].lower():
508	            # a page's server HTML is not what the browser shows (scripts fill in and change it): open it instead
509	            return f"{url} is a web page, so it was opened in the browser:\n\n" + await self.goto(url)
510	        name = re.sub(r'.*filename\*?=(?:UTF-8\'\')?"?([^";]+)"?.*', r"\1", fetched["name"]) or url
511	        return f"Document {short(name, 120)} (HTTP {fetched['status']}, {fetched['type']}):\n" + extract(data, name, fetched["type"])
512	
513	
514	INVISIBLE = re.compile("[\u200b-\u200d\u2060\ufeff\u00ad]")
515	
516	
517	def extract(data: bytes, name: str = "", content_type: str = "") -> str:
518	    """Readable text from a PDF, a ZIP (each file inside), a Word file, HTML or plain text."""
519	    text = INVISIBLE.sub("", _extract(data, name.lower(), content_type.lower(), depth=0))
520	    return text if len(text) <= MAX_DOCUMENT else text[:MAX_DOCUMENT] + f"\n[… {len(text) - MAX_DOCUMENT} more characters]"
521	
522	
523	def _extract(data: bytes, name: str, content_type: str, depth: int) -> str:
524	    if data[:4] == b"%PDF":
525	        from pypdf import PdfReader
526	        reader = PdfReader(io.BytesIO(data))
527	        return "\n".join(f"--- page {i} ---\n{page.extract_text() or ''}" for i, page in enumerate(reader.pages, 1))
528	    if data[:2] == b"PK":
529	        archive = zipfile.ZipFile(io.BytesIO(data))
530	        names = archive.namelist()
531	        if "word/document.xml" in names:
532	            xml = archive.read("word/document.xml").decode("utf-8", "replace")
533	            return _strip_xml(xml.replace("</w:p>", "\n").replace("</w:tc>", " | "))
534	        if depth > 1:
535	            return f"(archive with {len(names)} files)"
536	        parts = [f"Archive with {len(names)} files: {', '.join(names)}"]
537	        for member in names:
538	            if not member.endswith("/"):
539	                parts.append(f"=== {member} ===\n" + _extract(archive.read(member), member.lower(), "", depth + 1))
540	        return "\n".join(parts)
541	    for encoding in ("utf-8", "cp1252"):
542	        try:
543	            text = data.decode(encoding)
544	            break
545	        except UnicodeDecodeError:
546	            continue
547	    else:
548	        text = data.decode("utf-8", "replace")
549	    if "html" in content_type or name.endswith((".html", ".htm")) or re.search(r"<(html|body|table|div)\b", text[:2000], re.I):
550	        return html_text(text)
551	    if name.endswith(".xml") or text.lstrip().startswith("<?xml"):
552	        return _strip_xml(text)
553	    return text
