560	class _Text(HTMLParser):
561	    BLOCK = {"p", "div", "br", "li", "h1", "h2", "h3", "h4", "h5", "h6", "section", "article", "table", "ul", "ol"}
562	
563	    def __init__(self):
564	        super().__init__()
565	        self.parts, self.skip = [], 0
566	
567	    def handle_starttag(self, tag, attrs):
568	        if tag in ("script", "style"):
569	            self.skip += 1
570	        elif tag == "tr":
571	            self.parts.append("\n| ")
572	        elif tag in ("td", "th"):
573	            pass
574	        elif tag in self.BLOCK:
