577	    def handle_endtag(self, tag):
578	        if tag in ("script", "style"):
579	            self.skip = max(0, self.skip - 1)
580	        elif tag in ("td", "th"):
581	            self.parts.append(" | ")
582	
583	    def handle_data(self, data):
584	        if not self.skip:
585	            self.parts.append(data)
