588	def html_text(html: str) -> str:
589	    parser = _Text()
590	    parser.feed(html)
591	    text = "".join(parser.parts)
592	    return "\n".join(re.sub(r"[ \t ]+", " ", line).strip() for line in text.splitlines() if line.strip())
593	
