596	    """The browser tools every agent gets, as (OpenAI tool schema, coroutine) pairs."""
597	    ref = {"type": "integer", "description": "The element's number in the page view, e.g. 12 for [12 button ...]"}
598	    return [
599	        (_tool("view", "Show the current page again (it may have changed by itself).", {}), site.view),
600	        (_tool("more", "Show the next part of a long page.", {}), site.more),
601	        (_tool("find", "Search the current page's full text for a word or number; returns the matching lines.",
602	               {"text": {"type": "string"}}, ["text"]), site.find),
603	        (_tool("click", "Click an element: a link, button, tab, row, checkbox, ...", {"ref": ref}, ["ref"]), site.click),
604	        (_tool("fill", "Enter values into several form fields at once. Text inputs get the text, selects the option "
605	                       "label, checkboxes and radios true or false. Does not submit.",
606	               {"fields": {"type": "array", "items": {"type": "object", "properties": {
607	                   "ref": ref, "value": {"type": ["string", "number", "boolean"]}}, "required": ["ref", "value"]}}},
608	               ["fields"]), site.fill),
609	        (_tool("type", "Type text into one input, optionally pressing Enter afterwards (to search, for example).",
610	               {"ref": ref, "text": {"type": "string"}, "enter": {"type": "boolean"}}, ["ref", "text"]), site.type),
611	        (_tool("drag", "Drag an element with the mouse: a slider handle or range input (without dx: all the way to "
612	                       "the right end), or any draggable item by dx/dy pixels.",
613	               {"ref": ref, "dx": {"type": "number"}, "dy": {"type": "number"}}, ["ref"]), site.drag),
614	        (_tool("press", "Press a key (Enter, Escape, Tab, F4, ArrowDown, ...), on an element or the page.",
615	               {"key": {"type": "string"}, "ref": ref}, ["key"]), site.press),
616	        (_tool("goto", "Open a URL or a path on this website.", {"url": {"type": "string"}}, ["url"]), site.goto),
617	        (_tool("reload", "Reload the page, e.g. after an error page.", {}), site.reload),
618	        (_tool("back", "Browser back. Never use it inside a multi-step form: it clears the later steps.", {}), site.back),
619	        (_tool("switch_tab", "Make another open tab the active one (numbers as in the Tabs line).",
620	               {"index": {"type": "integer"}}, ["index"]), site.switch_tab),
621	        (_tool("login", "Log in: fills this website's username and password into the visible login form and submits "
622	                        "it. Use it whenever a login page appears, including after a session expired.", {}), site.login),
623	        (_tool("read_document", "Read a file as text: a link to a PDF, ZIP, Word, CSV or text file, a frame whose "
624	                                "content is not shown, or a downloaded file. Not for web pages: open those with "
625	                                "goto or click. Give the element number, a url, or the download number.",
626	               {"ref": ref, "url": {"type": "string"}, "download": {"type": "integer"}}), site.read_document),
627	        (_tool("screenshot", "Look at the screen as an image, when the text view leaves something unclear (a value "
628	                             "that seems hidden, a layout, a code shown as a picture).", {}), site.screenshot),
629	        (_tool("wait", "Wait some seconds (at most 30), then show the page.", {"seconds": {"type": "number"}},
