content.content:
1	"""The browser side: a compact text view of whatever page is open, and actions on its numbered elements.
2	
3	Nothing here knows the websites. The view renders any page the same way: text in reading order, tables as rows,
4	frames after the page, and every element the model can act on as [n kind "label"]. Code helps where the brief allows
5	it (logging in with the run's credentials, retrying error pages, reading a document the model picked); the model
6	chooses where to go and what to do.
7	"""
8	import asyncio
9	import base64
10	import io
11	import re
12	import tempfile
13	import zipfile
14	from html.parser import HTMLParser
15	from pathlib import Path
16	from urllib.parse import urljoin, urlparse
17	
