22	# Renders the document of one frame and numbers what can be acted on, starting at `start`.
23	RENDER = r"""
24	(start) => {
25	  let n = start, line = '', inCell = 0;
26	  const lines = [];
27	  const flush = () => { const t = line.replace(/[​-‍⁠﻿­]/g, '').replace(/[ \t ]+/g, ' ').trim(); if (t && t !== lines[lines.length - 1]) lines.push(t); line = ''; };
28	  const brk = () => { if (inCell) line += ' '; else flush(); };
29	  const clip = (s, k) => { s = String(s || '').replace(/[​-‍⁠﻿­]/g, '').replace(/\s+/g, ' ').trim(); return s.length > k ? s.slice(0, k) + '…' : s; };
30	  const q = (s) => JSON.stringify(s);
31	  const SKIP = new Set(['SCRIPT', 'STYLE', 'NOSCRIPT', 'TEMPLATE', 'HEAD', 'META', 'LINK', 'OPTION', 'defs', 'style']);
32	  const generated = (el, which) => {  // text a style sheet adds before or after an element
33	    const c = getComputedStyle(el, which).content;
34	    return c && c !== 'none' && c !== 'normal' && /^["']/.test(c) ? c.slice(1, -1) : '';
35	  };
36	  const ROLES = new Set(['button', 'link', 'tab', 'menuitem', 'menuitemcheckbox', 'menuitemradio', 'checkbox', 'radio',
37	    'option', 'switch', 'treeitem', 'combobox', 'textbox', 'searchbox']);
38	  const CONTROLS = 'a[href],button,input:not([type=hidden]),select,textarea,[role=button],[role=link],[onclick]';
39	  document.querySelectorAll('[data-agent-ref]').forEach((e) => e.removeAttribute('data-agent-ref'));
40	  // collapsed sections (▶ summaries) hide message texts, document contents and form fields: open them, so the view
41	  // shows what is inside under the summary that names it
42	  document.querySelectorAll('details:not([open])').forEach((d) => { d.open = true; });
43	
44	  const labelOf = (el) => {
45	    let s = el.getAttribute('aria-label') || '';
46	    if (!s && el.labels && el.labels.length) s = [...el.labels].map((l) => l.innerText).join(' ');
47	    const by = el.getAttribute('aria-labelledby');
48	    if (!s && by) s = by.split(/\s+/).map((i) => (document.getElementById(i) || {}).innerText || '').join(' ');
49	    return clip(s || el.getAttribute('title') || el.getAttribute('placeholder') || el.name || '', 80);
50	  };
51	  const pointer = (el) => {
52	    const parent = el.parentElement;
53	    return getComputedStyle(el).cursor === 'pointer' && !(parent && getComputedStyle(parent).cursor === 'pointer')
54	      && clip(el.innerText, 300).length < 200 && !el.querySelector(CONTROLS) && !(el.tagName === 'LABEL' && el.control);
55	  };
56	  const interactive = (el) => {
57	    const t = el.tagName;
58	    if (t === 'A') return el.hasAttribute('href') || el.hasAttribute('onclick');
59	    if (t === 'BUTTON' || t === 'SELECT' || t === 'TEXTAREA' || t === 'SUMMARY') return true;
60	    if (t === 'INPUT') return el.type !== 'hidden';
61	    if (el.querySelector(CONTROLS)) return false;  // a container: its controls are listed instead
62	    const role = el.getAttribute('role');
63	    if (role && ROLES.has(role)) return true;
64	    if (el.hasAttribute('onclick') || (el.hasAttribute('tabindex') && el.tabIndex >= 0)) return true;
65	    if (el.isContentEditable && !(el.parentElement && el.parentElement.isContentEditable)) return true;
66	    return pointer(el);
67	  };
68	  const render = (el) => {
69	    const t = el.tagName, id = n++;
70	    el.setAttribute('data-agent-ref', id);
71	    const off = el.disabled || el.getAttribute('aria-disabled') === 'true' ? ' disabled' : '';
72	    if (t === 'INPUT' || t === 'TEXTAREA') {
73	      const type = t === 'TEXTAREA' ? 'textarea' : (el.type || 'text');
74	      if (type === 'checkbox' || type === 'radio') return `[${id} ${type} ${q(labelOf(el))}${el.checked ? ' checked' : ''}${off}]`;
75	      if (['submit', 'button', 'reset', 'image'].includes(type)) return `[${id} button ${q(clip(el.value || labelOf(el) || type, 80))}${off}]`;
76	      if (type === 'file') return `[${id} file-input ${q(labelOf(el))}${off}]`;
77	      const kind = type === 'text' ? 'input' : `${type}-input`;
78	      return `[${id} ${kind} ${q(labelOf(el))} value=${q(clip(el.value, 120))}${el.readOnly ? ' readonly' : ''}${el.required ? ' required' : ''}${off}]`;
79	    }
80	    if (t === 'SELECT') {
81	      const opts = [...el.options];
82	      const chosen = opts.filter((o) => o.selected).map((o) => clip(o.text, 60)).join(', ');
83	      const list = opts.slice(0, 40).map((o) => q(clip(o.text, 60))).join(' | ');
84	      return `[${id} select ${q(labelOf(el))} selected=${q(chosen)} options: ${list}${opts.length > 40 ? ` | … ${opts.length - 40} more` : ''}${off}]`;
85	    }
86	    const role = el.getAttribute('role') || (t === 'A' ? 'link' : (t === 'BUTTON' || t === 'SUMMARY') ? 'button' : 'clickable');
87	    const text = clip(el.innerText || el.getAttribute('aria-label') || el.getAttribute('title') || el.value || '', 100);
88	    let to = '';
89	    const href = t === 'A' ? el.getAttribute('href') : '';
90	    if (href && !href.startsWith('javascript') && href !== '#') {
91	      try {  // one odd link must not cost the whole page its view
92	        const u = new URL(el.href, location.href);
93	        to = ' → ' + (u.origin === location.origin ? u.pathname + u.search + u.hash : u.href);
94	      } catch (e) { to = ' → ' + href; }
95	    }
96	    const state = ['aria-selected', 'aria-checked', 'aria-expanded', 'aria-pressed', 'aria-current']
97	      .filter((a) => el.getAttribute(a) && el.getAttribute(a) !== 'false').map((a) => ' ' + a.slice(5)).join('');
98	    return `[${id} ${role} ${q(text)}${to}${state}${off}]`;
99	  };
100	  const walk = (node) => {
101	    if (node.nodeType === Node.TEXT_NODE) { line += node.textContent; return; }
102	    if (node.nodeType !== Node.ELEMENT_NODE) return;
103	    const el = node, t = el.tagName;
104	    if (SKIP.has(t)) return;
105	    const style = getComputedStyle(el);
106	    if (style.display === 'none' || style.visibility === 'hidden') return;
107	    if (t === 'IFRAME' || t === 'FRAME' || t === 'OBJECT' || t === 'EMBED') {
108	      brk(); line += `[frame ${q(el.title || el.name || '')} src=${q(clip(el.getAttribute('src') || el.getAttribute('data') || '', 160))}]`; brk();
109	      return;
110	    }
111	    if (t === 'BR' || t === 'HR') { brk(); return; }
112	    if (interactive(el)) {
113	      const control = ['A', 'BUTTON', 'INPUT', 'SELECT', 'TEXTAREA', 'SUMMARY', 'LABEL'].includes(t);
114	      if (control || clip(el.innerText, 200).length <= 100) { line += ' ' + render(el) + ' '; return; }
115	      // a focusable or clickable box with long content (a scrollable message, a table area): number it, then
116	      // show all of its text, which a short label would cut off
117	      const id = n++;
118	      el.setAttribute('data-agent-ref', id);
119	      brk(); line += `[${id} ${el.getAttribute('role') || 'box'}] `;
120	    }
121	    if (t === 'TR') {
122	      flush(); inCell++;
123	      for (const cell of el.children) { walk(cell); line += ' |'; }
124	      inCell--; line = '| ' + line; flush();
125	      return;
126	    }
127	    const role = el.getAttribute('role');
128	    const block = !style.display.startsWith('inline') || /^H[1-6]$/.test(t) || t === 'LI';
129	    if (block) brk();
130	    if (/^H[1-6]$/.test(t) && !inCell) line += '#'.repeat(+t[1]) + ' ';
131	    if (t === 'LI' && !inCell) line += '- ';
132	    if (t === 'DIALOG' || role === 'dialog' || role === 'alertdialog' || el.getAttribute('aria-modal') === 'true') { line += '[dialog] '; }
133	    if (role === 'alert' || role === 'status') line += '[notice] ';
134	    line += generated(el, '::before');
135	    for (const child of el.childNodes) walk(child);
136	    line += generated(el, '::after');
137	    if (el.shadowRoot) for (const child of el.shadowRoot.childNodes) walk(child);
138	    if (block) brk();
139	  };
140	  if (document.body) walk(document.body);
141	  flush();
142	  return { text: lines.join('\n'), next: n };
143	}
144	"""
