146	# Marks the visible login form's user and password fields, for login().
147	MARK_LOGIN = r"""
148	() => {
149	  const visible = (e) => { const r = e.getBoundingClientRect(), s = getComputedStyle(e); return r.width > 0 && r.height > 0 && s.visibility !== 'hidden' && s.display !== 'none'; };
150	  document.querySelectorAll('[data-agent-login]').forEach((e) => e.removeAttribute('data-agent-login'));
151	  const password = [...document.querySelectorAll('input[type=password]')].find(visible);
152	  if (!password) return false;
153	  const fields = [...(password.form || document).querySelectorAll('input')].filter((e) => visible(e)
154	    && !['password', 'hidden', 'checkbox', 'radio', 'submit', 'button', 'image', 'reset'].includes(e.type));
155	  const before = fields.filter((e) => e.compareDocumentPosition(password) & Node.DOCUMENT_POSITION_FOLLOWING);
156	  const user = before.length ? before[before.length - 1] : fields[0];
157	  password.setAttribute('data-agent-login', 'password');
158	  if (user) user.setAttribute('data-agent-login', 'user');
159	  return true;
160	}
161	"""
