163	# Finds the visible selection field whose own label (without its options) matches, marks it, and lists its options.
164	FIND_SELECT = r"""
165	(label) => {
166	  const norm = (s) => String(s || '').replace(/[​-‍⁠﻿­]/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
167	  const own = (el) => {
168	    if (el.labels && el.labels.length) {
169	      const copy = el.labels[0].cloneNode(true);
170	      copy.querySelectorAll('select,option,input,textarea,button').forEach((x) => x.remove());
171	      if (norm(copy.textContent)) return norm(copy.textContent);
172	    }
173	    return norm(el.getAttribute('aria-label') || el.getAttribute('title') || el.name || '');
174	  };
175	  document.querySelectorAll('[data-agent-pick]').forEach((e) => e.removeAttribute('data-agent-pick'));
176	  const want = norm(label);
177	  const shown = [...document.querySelectorAll('select')].filter((s) => { const r = s.getBoundingClientRect(); return r.width > 0 && r.height > 0; });
178	  const hit = shown.find((s) => own(s) === want) || shown.find((s) => own(s).startsWith(want))
179	    || shown.find((s) => own(s).includes(want)) || shown.find((s) => own(s) && want.includes(own(s)));
180	  if (!hit) return null;
181	  hit.setAttribute('data-agent-pick', 'select');
182	  return { label: own(hit), disabled: hit.disabled, options: [...hit.options].map((o) => ({ text: o.text.replace(/\s+/g, ' ').trim(), value: o.value })) };
183	}
184	"""
