188	(text) => {
189	  const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();
190	  document.querySelectorAll('[data-agent-pick=button]').forEach((e) => e.removeAttribute('data-agent-pick'));
191	  const want = norm(text);
192	  const hit = [...document.querySelectorAll('button,input[type=submit],input[type=button],[role=button]')].find((b) => {
