202	# Fetches a URL inside the page, with its cookies and through the browser's own network path.
203	FETCH = r"""
204	async (url) => {
205	  const r = await fetch(url, { credentials: 'include' });
206	  const bytes = new Uint8Array(await r.arrayBuffer());
207	  let bin = '';
208	  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
209	  return { status: r.status, type: r.headers.get('content-type') || '', name: r.headers.get('content-disposition') || '',
210	           url: r.url, data: btoa(bin) };
211	}
212	"""
