220	class Site:
221	    """One website, driven in its own browser: the active tab, its numbered elements, dialogs, new tabs, downloads."""
222	
223	    def __init__(self, access: dict, context, page, log=print):
224	        self.id = access.get("siteId") or urlparse(access["url"]).hostname
225	        self.url = access["url"]
226	        self.credentials = access.get("credentials") or {}
227	        self.context, self.page, self.log = context, page, log
228	        self.refs: dict[int, object] = {}  # element number -> the frame it is in
229	        self.events: list[str] = []  # dialogs, tabs and downloads since the last view
230	        self.downloads: list[Path] = []
231	        self.full_view, self.shown = "", 0
232	        self.lock = asyncio.Lock()  # one agent at a time drives this browser
233	        context.on("page", self._new_tab)
234	        self._watch(page)
235	
236	    # --- events -------------------------------------------------------------------------------------------------
237	
238	    def _watch(self, page):
239	        page.on("dialog", self._dialog)
240	        page.on("download", self._download)
241	
242	    def _new_tab(self, page):
243	        self._watch(page)
244	        self.page = page
245	        self.events.append("A new tab opened and is now the active tab.")
246	
247	    async def _dialog(self, dialog):
248	        # Browser dialogs block the page until answered. The agents only trigger them on purpose (the final
249	        # confirmation of a bid is one), so they are accepted and reported in the next view.
250	        self.events.append(f"A browser {dialog.type} dialog said {short(dialog.message)!r}; it was accepted.")
251	        try:
252	            await dialog.accept()
253	        except Exception:
254	            pass
255	
256	    async def _download(self, download):
257	        target = Path(tempfile.mkdtemp()) / (download.suggested_filename or "download")
258	        try:
259	            await download.save_as(target)
260	        except Exception as error:
261	            self.events.append(f"A download failed: {short(error)}")
262	            return
263	        self.downloads.append(target)
264	        self.events.append(f"Downloaded {target.name!r}: read it with read_document(download={len(self.downloads)}).")
265	
266	    async def keep_alive(self):
267	        """Loads the current address in the background with this browser's cookies, leaving the page untouched: a
268	        website that logs out after a short idle time keeps the session while its agent waits."""
269	        try:
270	            await self.context.request.get(self.page.url, timeout=8000)
271	        except Exception:
272	            pass
273	
274	    async def fresh_tab(self, url: str | None = None) -> str:
275	        """A new tab in this website's browser (same login), made the active one: away from a page that is stuck."""
276	        page = await self.context.new_page()  # the context's "page" event watches it for dialogs and downloads
277	        self.page = page
278	        return await self.goto(url or self.url)
279	
280	    async def _active(self):
281	        if self.page.is_closed():
282	            open_pages = [page for page in self.context.pages if not page.is_closed()]
283	            self.page = open_pages[-1] if open_pages else await self.context.new_page()
284	            self.events.append("The tab closed; switched to the previous tab.")
285	        return self.page
286	
287	    async def _settle(self):
288	        page = await self._active()
289	        for state, timeout in (("domcontentloaded", 10000), ("networkidle", 1500)):
290	            try:
291	                await page.wait_for_load_state(state, timeout=timeout)
292	            except Exception:
293	                pass
294	        await asyncio.sleep(0.2)
295	
296	    # --- the view -----------------------------------------------------------------------------------------------
297	
298	    async def view(self) -> str:
299	        """The page as text, from the top; long pages are cut, more() shows the rest."""
300	        page = await self._active()
301	        self.refs, number, parts = {}, 1, []
302	        for frame in page.frames:
303	            try:
304	                rendered = await asyncio.wait_for(frame.evaluate(RENDER, number), FRAME_SECONDS)
305	            except asyncio.TimeoutError:
306	                # a page that stops answering scripts must not stop the agent: say so, it can reload or go elsewhere
307	                parts.append(f"--- {'the page' if frame is page.main_frame else 'frame ' + short(frame.url, 120)} "
308	                             "does not respond: reload() it, or goto() its address again ---")
309	                continue
310	            except Exception:
311	                continue
312	            for ref in range(number, rendered["next"]):
313	                self.refs[ref] = frame
314	            number = rendered["next"]
315	            if frame is page.main_frame:
316	                parts.insert(0, rendered["text"])
317	            elif rendered["text"].strip():
318	                parts.append(f"--- inside frame {frame.name or ''} {short(frame.url, 120)} ---\n{rendered['text']}")
319	            else:
320	                parts.append(f"--- frame {short(frame.url, 120)} shows nothing here: open it with goto() to read it ---")
321	        try:
322	            title = await asyncio.wait_for(page.title(), 5)
323	        except Exception:
324	            title = ""
325	        tabs = [p for p in self.context.pages if not p.is_closed()]
326	        header = f"URL: {page.url}\nTitle: {title}\n"
327	        if len(tabs) > 1:
328	            header += "Tabs: " + " | ".join(f"{i}{' (active)' if p is page else ''}: {short(p.url, 80)}"
329	                                            for i, p in enumerate(tabs)) + "\n"
330	        if self.events:
331	            header += "".join(f"Event: {event}\n" for event in self.events)
332	            self.events = []
333	        self.full_view = header + "\n" + "\n\n".join(parts)
334	        return self._part(0)
335	
336	    def _part(self, start: int) -> str:
337	        end = start + MAX_VIEW
338	        self.shown = end
339	        text = self.full_view[start:end]
340	        if start:
341	            text = f"[page text from character {start}]\n" + text
342	        if end < len(self.full_view):
343	            text += f"\n[… {len(self.full_view) - end} more characters: more() shows them, find(text) searches them]"
344	        return text
345	
346	    async def more(self) -> str:
347	        if self.shown >= len(self.full_view):
348	            return "That was the end of the page."
349	        return self._part(self.shown)
350	
351	    async def find(self, text: str) -> str:
352	        """Lines of the current page containing `text` (case-insensitive), with the line after each."""
353	        lines = self.full_view.splitlines()
354	        hits = [i for i, line in enumerate(lines) if text.lower() in line.lower()]
355	        if not hits:
356	            return f"{text!r} is not on the current page (as of the last view)."
357	        return "\n".join("\n".join(lines[i:i + 2]) for i in hits[:40])
358	
359	    # --- actions ------------------------------------------------------------------------------------------------
360	
361	    def _element(self, ref):
362	        frame = self.refs.get(int(ref))
363	        if frame is None:
364	            raise LookupError(f"There is no element [{ref}] on the page as last viewed; look at the current view.")
365	        return frame.locator(f'[data-agent-ref="{int(ref)}"]').first
366	
367	    async def click(self, ref) -> str:
368	        element = self._element(ref)
369	        try:
370	            # short: a popup that covers the page (they reappear on many pages) should cost seconds, not a minute
371	            await element.click(timeout=2500)
372	        except Exception as error:
373	            try:  # covered by an overlay or off screen: a DOM click still reaches the element's handler
374	                await element.evaluate("(e) => e.click()", timeout=3000)
375	            except Exception:
376	                return f"Could not click [{ref}]: {short(error)}\n\n" + await self.view()
377	        await self._settle()
378	        return await self.view()
379	
380	    async def fill(self, fields: list[dict]) -> str:
381	        """Several inputs at once: text is typed, selects choose the option by label or value, checkboxes take
382	        true/false."""
383	        problems = []
384	        for field in fields:
385	            ref, value = field.get("ref"), field.get("value")
386	            try:
387	                element = self._element(ref)
388	                # a field inside a collapsed section is not editable until the section is open
389	                kind = await element.evaluate("(e) => { for (let d = e.closest('details'); d; d = d.parentElement && "
390	                                              "d.parentElement.closest('details')) d.open = true; "
391	                                              "return e.tagName === 'SELECT' ? 'select' : (e.type || '').toLowerCase(); }",
392	                                              timeout=4000)
393	                if kind == "select":
394	                    try:
395	                        await element.select_option(label=str(value), timeout=3000)
396	                    except Exception:
397	                        await element.select_option(value=str(value), timeout=3000)
398	                elif kind in ("checkbox", "radio"):
399	                    want = value if isinstance(value, bool) else str(value).lower() in ("true", "1", "yes", "ja", "on")
400	                    try:
401	                        await element.set_checked(want, timeout=3000)
402	                    except Exception:
403	                        await element.set_checked(want, force=True, timeout=3000)
404	                else:
405	                    await element.fill(str(value), timeout=4000)
406	            except Exception as error:
407	                problems.append(f"[{ref}]: {short(error, 200)}")
408	        await self._settle()
409	        report = "Filled." if not problems else "Problems: " + "; ".join(problems)
410	        return report + "\n\n" + await self.view()
411	
412	    async def type(self, ref, text: str, enter: bool = False) -> str:
413	        element = self._element(ref)
414	        # only text fields take typing: on a button the fallback click below would press it (in run #5 that
415	        # silently omitted bid positions)
416	        kind = await element.evaluate("(e) => ({tag: e.tagName, type: (e.type || '').toLowerCase(), "
417	                                      "editable: e.isContentEditable})", timeout=4000)
418	        if kind["tag"] == "INPUT" and kind["type"] == "password":
419	            # an agent typing a search into a password field had been logged out without noticing (run #6)
420	            return ("[" + str(ref) + "] is a password field: this is a login form, so your session has probably "
421	                    "expired. Call login() to log in again, then go back to where you were. Nothing was typed.\n\n"
422	                    + await self.view())
423	        typable = kind["editable"] or kind["tag"] == "TEXTAREA" or (kind["tag"] == "INPUT" and kind["type"] in (
424	            "", "text", "search", "email", "number", "tel", "url", "date", "datetime-local", "time"))
425	        if not typable:
426	            return (f"[{ref}] is not a text field ({kind['tag'].lower()} {kind['type']}): nothing was typed or "
427	                    "clicked. Use click() for buttons and links, fill() for selects and checkboxes.\n\n"
428	                    + await self.view())
429	        try:
430	            await element.fill(text, timeout=4000)
431	        except Exception:
432	            await element.click(timeout=3000)
433	            await (await self._active()).keyboard.type(text)
434	        if enter:
435	            await element.press("Enter")
436	        await self._settle()
437	        return await self.view()
