655	def choose_option(options: list[dict], value) -> dict | None:
656	    """The option meant by `value`: the same text or value; else the only option whose text starts with it or
657	    contains it (e.g. a material number followed by a description); else, for a number, the smallest offered number
658	    not below it (the next nominal size). None when nothing fits."""
659	    def norm(text) -> str:
660	        return re.sub(r"\s+", " ", INVISIBLE.sub("", str(text))).strip().lower()
661	
662	    want = norm(value)
663	    real = [option for option in options if option.get("value") not in ("", None)]
664	    exact = [o for o in real if want in (norm(o["text"]), norm(o["value"]))]
665	    if exact:
666	        return exact[0]
667	    for test in (lambda o: norm(o["text"]).startswith(want), lambda o: want in norm(o["text"])):
668	        hits = [o for o in real if want and test(o)]
669	        if len(hits) == 1:
670	            return hits[0]
671	    wanted = _number(value)
672	    if wanted is not None and re.fullmatch(r"-?\d+(?:[.,]\d+)?\s*\w{0,3}", want):
673	        above = [(n, o) for o in real if (n := _number(o["text"])) is not None and n >= wanted]
674	        if above:
675	            return min(above, key=lambda pair: pair[0])[1]
676	    return None
