701	def _extract(data: bytes, name: str, content_type: str, depth: int) -> str:
702	    if data[:4] == b"%PDF":
703	        from pypdf import PdfReader
704	        reader = PdfReader(io.BytesIO(data))
705	        return "\n".join(f"--- page {i} ---\n{page.extract_text() or ''}" for i, page in enumerate(reader.pages, 1))
706	    if data[:2] == b"PK":
707	        archive = zipfile.ZipFile(io.BytesIO(data))
708	        names = archive.namelist()
709	        if "word/document.xml" in names:
710	            xml = archive.read("word/document.xml").decode("utf-8", "replace")
711	            return _strip_xml(xml.replace("</w:p>", "\n").replace("</w:tc>", " | "))
712	        if depth > 1:
713	            return f"(archive with {len(names)} files)"
714	        parts = [f"Archive with {len(names)} files: {', '.join(names)}"]
715	        for member in names:
716	            if not member.endswith("/"):
717	                parts.append(f"=== {member} ===\n" + _extract(archive.read(member), member.lower(), "", depth + 1))
718	        return "\n".join(parts)
719	    for encoding in ("utf-8", "cp1252"):
720	        try:
721	            text = data.decode(encoding)
722	            break
723	        except UnicodeDecodeError:
724	            continue
725	    else:
726	        text = data.decode("utf-8", "replace")
727	    if "html" in content_type or name.endswith((".html", ".htm")) or re.search(r"<(html|body|table|div)\b", text[:2000], re.I):
728	        return html_text(text)
729	    if name.endswith(".xml") or text.lstrip().startswith("<?xml"):
730	        return _strip_xml(text)
731	    return text
