738	class _Text(HTMLParser):
739	    BLOCK = {"p", "div", "br", "li", "h1", "h2", "h3", "h4", "h5", "h6", "section", "article", "table", "ul", "ol"}
740	
741	    def __init__(self):
742	        super().__init__()
